#!/usr/bin/env bash
# Host KAT runner: the core derives exactly the addresses in the shared derivation vectors
# (vectors/derivation/abandon-about.txt in the core, generated by an independent
# implementation, vectors/derivation/generate.py). The iOS test target reads the same file.
#
#   RED    -DDERIVATION_VECTORS_RED makes plausible porting mistakes in the KAT itself (wrong
#          master key per tree, Taproot over m/84', legacy chains swapped, the single-tree
#          wallet). Every RED case MUST fail, which proves the comparison is not vacuous; every
#          GUARD case must pass.
#   GREEN  the core as shipped: every case passes, ALL PASS, exit 0. Both arms under ASan.
#
# CORE_DIR may be set to run against a core checkout other than the android submodule.
# Exit code 0 = gate held, 1 = it did not.
set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../../../../.." && pwd)"
CORE_DIR="${CORE_DIR:-$REPO_ROOT/native/src/main/jni/digibytewallet-core}"
VECTOR_FILES=("$CORE_DIR/vectors/derivation/abandon-about.txt" "$CORE_DIR/vectors/derivation/abandon-about-trezor.txt")
BUILD_DIR="$(mktemp -d)"
trap 'rm -rf "$BUILD_DIR"' EXIT

CC="${CC:-clang}"
export ASAN_OPTIONS="halt_on_error=1 abort_on_error=1 detect_leaks=0 symbolize=0"
SAN_RE='ERROR: AddressSanitizer|runtime error:'

RED_CASES=(bip84_from_master_pubkey bip84_from_signing_key bip86_from_master_pubkey
           bip86_from_signing_key legacy_p2pkh_from_master_pubkey legacy_p2pkh_from_signing_key
           legacy_p2wpkh_from_master_pubkey legacy_p2wpkh_from_signing_key
           recipe_wallet_watches_every_vector)
GUARD_CASES=(vectors_parsed bip39_seed)

shopt -s nullglob
SHA3_SRCS=("$CORE_DIR"/crypto/sha3/*.c)
shopt -u nullglob

UNITS=(
    "$CORE_DIR/BRWallet.c"
    "$CORE_DIR/BRWalletFilterElements.c"
    "$CORE_DIR/BRTransaction.c"
    "$CORE_DIR/BRDigiDollar.c"
    "$CORE_DIR/BRKey.c"
    "$CORE_DIR/BRNetwork.c"
    "$CORE_DIR/BRBIP32Sequence.c"
    "$CORE_DIR/BRBIP39Mnemonic.c"
    "$CORE_DIR/BRAddress.c"
    "$CORE_DIR/BRSet.c"
    "$CORE_DIR/BRDigiAsset.c"
    "$CORE_DIR/BRCrypto.c"
    "$CORE_DIR/BRBase58.c"
    "$CORE_DIR/BRBech32.c"
    "$CORE_DIR/crypto/groestl.c"
    "$CORE_DIR/crypto/skein.c"
    "$CORE_DIR/crypto/qubit.c"
    "$CORE_DIR/crypto/odocrypt.c"
    "${SHA3_SRCS[@]}"
)

build() {
    local out="$1"; shift
    "$CC" -w -include stdint.h -g -fsanitize=address -fno-omit-frame-pointer "$@" \
        -I "$CORE_DIR" \
        -I "$CORE_DIR/secp256k1/include" \
        "$SCRIPT_DIR/derivation_vectors_kat_main.c" \
        "${UNITS[@]}" \
        -lpthread -lm \
        -o "$out"
}

for VECTORS in "${VECTOR_FILES[@]}"; do
    [ -s "$VECTORS" ] || { echo "GATE FAILURE: no vector file at $VECTORS."; exit 1; }
done

FAIL=0
build "$BUILD_DIR/red" -DDERIVATION_VECTORS_RED || { echo "GATE FAILURE: comparison arm did not compile."; exit 1; }
build "$BUILD_DIR/green" || { echo "GATE FAILURE: shipped arm did not compile."; exit 1; }

for VECTORS in "${VECTOR_FILES[@]}"; do
echo "=== $(basename "$VECTORS")"
echo "--- COMPARISON ARM (-DDERIVATION_VECTORS_RED): every RED case MUST fail, every GUARD case pass ---"
out="$("$BUILD_DIR/red" "$VECTORS" 2>&1)"; rc=$?
<<<"$out" grep -Eq "$SAN_RE" && { echo "  [red] GATE FAILURE: sanitizer report"; FAIL=1; }
[ $rc -eq 0 ] && { echo "  [red] GATE FAILURE: the comparison arm exited 0; it proves nothing"; FAIL=1; }
for c in "${RED_CASES[@]}"; do
    if <<<"$out" grep -q "^RESULT $c fail$"; then echo "  [red $c] failed, as it must"
    else echo "  [red $c] GATE FAILURE: did not fail in the comparison arm"; FAIL=1; fi
done
for c in "${GUARD_CASES[@]}"; do
    if <<<"$out" grep -q "^RESULT $c pass$"; then echo "  [red $c] GUARD held"
    else echo "  [red $c] GATE FAILURE: GUARD case did not hold"; <<<"$out" grep "^FAIL: $c" | sed 's/^/      /'; FAIL=1; fi
done

echo "--- SHIPPED ARM: every case MUST pass, ALL PASS, exit 0, no sanitizer report ---"
out="$("$BUILD_DIR/green" "$VECTORS" 2>&1)"; rc=$?
<<<"$out" grep -Eq "$SAN_RE" && { echo "  [green] GATE FAILURE: sanitizer report"; FAIL=1; }
if [ $rc -ne 0 ] || ! <<<"$out" grep -q "^ALL PASS$"; then
    echo "  [green] GATE FAILURE: shipped arm did not pass (rc=$rc)"; <<<"$out" grep "^FAIL:" | sed 's/^/      /'; FAIL=1
fi
for c in "${RED_CASES[@]}" "${GUARD_CASES[@]}"; do
    <<<"$out" grep -q "^RESULT $c pass$" && echo "  [green $c] passed" || { echo "  [green $c] GATE FAILURE: not passed"; FAIL=1; }
done

done

[ $FAIL -eq 0 ] && echo "derivation_vectors_kat: GATE HELD (the core derives and watches every independent vector, with and without a passphrase)"
exit $FAIL
